<?php
require_once 'auth.php'; require_admin(); require_once 'admin-functions.php';
$jobId=(int)($_GET['job_id']??$_POST['job_id']??0); if($jobId<=0){header('Location: admin-managejobs.php');exit;}
$stmt=$conn->prepare("SELECT j.*, COUNT(a.application_id) application_count FROM jobs j LEFT JOIN applications a ON a.job_id=j.job_id WHERE j.job_id=? GROUP BY j.job_id"); $stmt->bind_param('i',$jobId); $stmt->execute(); $job=$stmt->get_result()->fetch_assoc(); if(!$job){header('Location: admin-managejobs.php');exit;}
$locked=(int)$job['application_count']>0; $error=''; $allowanceOptions=fixed_allowance_options();
if($_SERVER['REQUEST_METHOD']==='POST' && !$locked){$title=trim($_POST['job']??'');$location=trim($_POST['location']??'');$jobDate=trim($_POST['job_date']??'');$allowance=trim($_POST['allowance']??'');$todo=trim($_POST['todo']??'');$amt=$allowanceOptions[$allowance]??admin_allowance_amount($allowance); if($title&&$location&&$jobDate&&$allowance&&$todo){$u=$conn->prepare("UPDATE jobs SET title=?,location=?,job_date=?,allowance=?,allowance_amount=?,todo=? WHERE job_id=? AND NOT EXISTS (SELECT 1 FROM applications WHERE job_id=?)");$u->bind_param('ssssdssi',$title,$location,$jobDate,$allowance,$amt,$todo,$jobId,$jobId);$u->execute();header('Location: admin-managejobs.php?updated=1');exit;}else $error='Please fill all fields.';}
?>
<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Edit Job</title><link rel="stylesheet" href="admin-style.css?v=10"></head><body><?php include 'admin-header.php'; ?><main class="page-panel"><section class="form-wrap"><h1><?php echo $locked?'View Job':'Edit Job'; ?></h1><?php if($locked): ?><p class="centered-note" style="color:#c0392b">This job is locked because student already applied. Business logic: update is blocked.</p><?php endif; ?><?php if($error): ?><p class="centered-note" style="color:#c0392b"><?php echo e($error); ?></p><?php endif; ?><form method="post"><input type="hidden" name="job_id" value="<?php echo $jobId; ?>"><div class="form-row"><label>Job</label><input name="job" value="<?php echo e($job['title']); ?>" <?php echo $locked?'readonly':''; ?>></div><div class="form-row"><label>Location</label><input name="location" value="<?php echo e($job['location']); ?>" <?php echo $locked?'readonly':''; ?>></div><div class="form-row"><label>Date</label><input type="date" name="job_date" value="<?php echo e($job['job_date']); ?>" <?php echo $locked?'readonly':''; ?>></div><div class="form-row"><label>Allowance</label><select name="allowance" <?php echo $locked?'disabled':''; ?>><?php foreach($allowanceOptions as $label=>$v): ?><option value="<?php echo e($label); ?>" <?php echo $job['allowance']===$label?'selected':''; ?>><?php echo e($label); ?></option><?php endforeach; ?></select><?php if($locked): ?><input type="hidden" name="allowance" value="<?php echo e($job['allowance']); ?>"><?php endif; ?></div><div class="form-row"><label>To Do</label><textarea name="todo" <?php echo $locked?'readonly':''; ?>><?php echo e($job['todo']); ?></textarea></div><?php if(!$locked): ?><button class="submit-job">Update Job</button><?php endif; ?><a class="add-job" href="admin-managejobs.php">Back</a></form></section></main></body></html>
